/*Table structure for table `complain` */

DROP TABLE IF EXISTS `complain`;

CREATE TABLE `complain` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_by` varchar(255) DEFAULT NULL,
  `created_datetime` datetime(6) DEFAULT NULL,
  `modified_by` varchar(255) DEFAULT NULL,
  `modified_datetime` datetime(6) DEFAULT NULL,
  `complain` varchar(225) DEFAULT NULL,
  `status` varchar(225) DEFAULT NULL,
  `subject` varchar(225) DEFAULT NULL,
  `user_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `complain` */

insert  into `complain`(`id`,`created_by`,`created_datetime`,`modified_by`,`modified_datetime`,`complain`,`status`,`subject`,`user_id`) values 
(1,NULL,NULL,NULL,NULL,'sfvsf','Complete','dfvdf',2),
(2,NULL,NULL,NULL,NULL,'dsv','Pending','adv',2);

/*Table structure for table `house` */

DROP TABLE IF EXISTS `house`;

CREATE TABLE `house` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_by` varchar(255) DEFAULT NULL,
  `created_datetime` datetime(6) DEFAULT NULL,
  `modified_by` varchar(255) DEFAULT NULL,
  `modified_datetime` datetime(6) DEFAULT NULL,
  `block_no` varchar(225) DEFAULT NULL,
  `detail` varchar(225) DEFAULT NULL,
  `house_type` varchar(225) DEFAULT NULL,
  `name` varchar(225) DEFAULT NULL,
  `society_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `FKiv09wvudq15ukc2vcilhy13fy` (`society_id`),
  CONSTRAINT `FKiv09wvudq15ukc2vcilhy13fy` FOREIGN KEY (`society_id`) REFERENCES `society` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `house` */

insert  into `house`(`id`,`created_by`,`created_datetime`,`modified_by`,`modified_datetime`,`block_no`,`detail`,`house_type`,`name`,`society_id`) values 
