/*Table structure for table `rent` */

DROP TABLE IF EXISTS `rent`;

CREATE TABLE `rent` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_by` varchar(255) DEFAULT NULL,
  `created_datetime` datetime(6) DEFAULT NULL,
  `modified_by` varchar(255) DEFAULT NULL,
  `modified_datetime` datetime(6) DEFAULT NULL,
  `price` varchar(225) DEFAULT NULL,
  `society_id` bigint NOT NULL,
  `type` varchar(225) DEFAULT NULL,
  `allocate` bigint NOT NULL,
  `house` bigint NOT NULL,
  `society` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `FK91uahwf3v1pag2j5w8h82omt5` (`house`),
  KEY `FKka6jfgyn6bjr57s6ow2ssv2t3` (`allocate`),
  KEY `FKt9r60h66jf2epfmx4svirqc57` (`society`),
  CONSTRAINT `FK91uahwf3v1pag2j5w8h82omt5` FOREIGN KEY (`house`) REFERENCES `house` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FKka6jfgyn6bjr57s6ow2ssv2t3` FOREIGN KEY (`allocate`) REFERENCES `allocate` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FKt9r60h66jf2epfmx4svirqc57` FOREIGN KEY (`society`) REFERENCES `society` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

